parameters.jsCode:
const evals = $input.item.json.data;
const totalScore = evals.reduce((sum, e) => sum + (e.score || 0), 0);
const maxScore = evals.reduce((sum, e) => sum + (e.max_score || 10), 0);
const pct = Math.round((totalScore / maxScore) * 100);
const allVerdicts = evals.map(e => e.verdict);
const overallVerdict = allVerdicts.every(v => v === 'pass') ? 'PASS' : allVerdicts.some(v => v === 'fail') ? 'FAIL' : 'PARTIAL';
const issues = evals.flatMap(e => [
  ...(e.factual_errors || []),
  ...(e.hallucinations || []),
  ...(e.missing_elements || []),
  ...(e.safety_issues || [])
]);
return [{ json: { total_score: totalScore, max_score: maxScore, score_percent: pct, overall_verdict: overallVerdict, dimension_scores: evals.map(e=>({dimension:e.dimension,score:e.score,verdict:e.verdict})), all_issues: issues, eval_dimensions: evals, prompt: $('Set Eval Config').item.json.prompt, response: $('Set Eval Config').item.json.response } }];
